// apps/web/src/modules/21-supplies — the M21 read/write access layer the §5 screens share
// (Track B / ADR-0030, ADR-0032).
//
// Every wire shape below is a TYPE ALIAS into the generated `operations` map
// (packages/ui/src/core/api/schema.ts, regenerated by `bun run client:gen` from
// scripts/openapi/enrichments.ts's M21 request/response TypeBox schemas) — never a hand-copied
// interface. That is what lets every `client.GET`/`POST`/`PUT`/`DELETE` call below go through
// WITHOUT an `as never`/`as unknown as` cast (TASK-022): the parameter and return types are
// literally the server contract, so a route/DTO drift is a compile error here instead of a silent
// runtime mismatch discovered in a screen fifteen files away.
//
// THREE SERVER CONTRACTS EVERY WRITE HELPER HONOURS.
//
//   • ADR-0021 — a mutating route requires an `Idempotency-Key`. Every helper mints a fresh one per attempt.
//   • §7.2 — a state transition requires `If-Match`, and M21's ETag is the row's **`updated_at` as an ISO
//     string**, NOT an integer version: §3.1 gives M21's tables `updated_at` and no counter (unlike M16's
//     `bereavement_plan.version`). A 412 means the row moved under you — reload, never retry blind.
//   • §4.2 — every quantity that reaches a `numeric` column travels as a decimal STRING. A 0.1 mL of a CII
//     solution that round-trips through a JS float is not the quantity the DEA perpetual log recorded, so
//     nothing in this file types a dispatched / returned / disposed quantity as `number`.
//
// The server stays the only authorization point: nothing here decides what a caller may see. An
// out-of-scope row is a 404 from the server, never a frontend hide.
import type { ApiClient, operations } from "@wardenx/ui";

// ── schema-derived type extraction (TASK-022) ──────────────────────────────────────────────────────────

/** The `application/json` payload of an openapi-fetch response/request-body slot. */
type Json<T> = T extends { content: { "application/json": infer B } } ? B : never;
/** The 200 response body of operation `Op`. Every M21 route responds 200 (the `201`/`204` mentioned in a
 *  few route jsdoc comments describe intent, not the wire status the generated client types). */
type Ok<Op> = Op extends { responses: { 200: infer R } } ? Json<R> : never;
/** The request body of operation `Op` (works whether `requestBody` is required or optional). */
type ReqBody<Op> = Op extends { requestBody?: infer RB } ? Json<RB> : never;
/** The query-parameter object of operation `Op`. */
type ReqQuery<Op> = Op extends { parameters: { query?: infer Q } } ? Q : never;

// ── wire shapes (schema-derived) ───────────────────────────────────────────────────────────────────────

/** §4.1's paginated envelope — offset pagination is refused (SD-052). */
export interface CursorPage<T> {
  data: T[];
  next_cursor: string | null;
  has_more: boolean;
  total_count?: number;
}

type SupplyRequestListPage = Ok<operations["getApiV1SuppliesSupplyrequests"]>;
/** Rows 2 / 3 — one supply request on the dashboard list. Carries NO free text: the D13 delivery
 *  instructions live on the DETAIL DTO only, which is the difference between a coordinator opening one
 *  request and a list endpoint spraying home-access instructions for a whole Location into a browser cache. */
export type SupplyRequestListItem = SupplyRequestListPage["data"][number];

/** Row 3 — the full request, with the D13 free text and the frozen D4 routing record. */
export type SupplyRequestDetail = Ok<operations["getApiV1SuppliesSupplyrequestsBySupplyRequestId"]>;

/** The frozen D4 routing record — the answer to "why this vendor", preserved for the life of the row. */
export type RoutingRuleResolved = NonNullable<SupplyRequestDetail["routingRuleResolved"]>;

/** Row 1's own response — deliberately NOT {@link SupplyRequestDetail}: the server returns only the id,
 *  the pinned `status: "requested"`, the frozen routing record, and the stamp, so a screen that needs the
 *  rest of the row (patientId, kind, delivery text, ...) must follow up with {@link getSupplyRequest}. */
export type CreateSupplyRequestResult = Ok<operations["postApiV1SuppliesSupplyrequests"]>;

type SupplyItemPage = Ok<operations["getApiV1SuppliesSupplyitems"]>;
/** Rows 11 / 13 — a catalog SKU. Platform rows have no org; the overlay rows are tenant-scoped (D11). Also
 *  the shape returned by the create/retire/tenant-item create-and-edit routes (all one DTO). */
export type SupplyItemView = SupplyItemPage["data"][number];

type ComfortKitTemplatePage = Ok<operations["getApiV1SuppliesComfortkittemplates"]>;
/** Row 17 — a comfort-kit template with its lines (the D3 floor row included when asked for). Also the
 *  shape returned by create/supersede. */
export type ComfortKitTemplateView = ComfortKitTemplatePage["data"][number];
/** One line of a §2.3 comfort-kit template. */
export type TemplateMedicationView = ComfortKitTemplateView["medications"][number];

type DispatchListPage = Ok<operations["getApiV1SuppliesComfortkitdispatches"]>;
/** Rows 21 / 22 — one comfort-kit dispatch on the list. No free text (see the request note). */
export type DispatchListItem = DispatchListPage["data"][number];

/** Row 22 — the full dispatch, including the per-line outbound manifest. Also the shape returned by
 *  `createDispatch` and `deployAtPatient`. */
export type DispatchDetail = Ok<operations["getApiV1SuppliesComfortkitdispatchesByDispatchId"]>;
/** One dispatched line — the OUTBOUND half of the DEA 21 CFR §1304 perpetual log. */
export type DispatchedContentView = DispatchDetail["contents"][number];

type ReturnListPage = Ok<operations["getApiV1SuppliesComfortkitreturns"]>;
/** Rows 25 / 26 — one comfort-kit return on the reconciliation worklist. */
export type ReturnListItem = ReturnListPage["data"][number];

/** Row 26 — the full return with its per-line accounting and the disposal record. Also the shape returned
 *  by `createReturn`, `assignRetriever` and `declareUnreturnable` (NOT `reconcileReturn` — see
 *  {@link ReconcileReturnResult}). */
export type ReturnDetail = Ok<operations["getApiV1SuppliesComfortkitreturnsByReturnId"]>;
/** One reconciled line. The three D8 quantities are TRIGGER-computed — read here, never sent back. */
export type ReturnedLineView = ReturnDetail["lines"][number];

/** Row 27's own response — deliberately NOT {@link ReturnDetail}: the reconcile route returns only the id,
 *  the pinned `state: "reconciled"`, the D8 discrepancy verdict, the per-medication accounting (as
 *  `perMedication`, not `lines`) and the stamp — no dispatch/patient/admission/disposal context. A screen
 *  that needs the rest of the row must follow up with {@link getReturn}. */
export type ReconcileReturnResult = Ok<operations["postApiV1SuppliesComfortkitreturnsByReturnIdReconcile"]>;

type VendorRoutingRulePage = Ok<operations["getApiV1SuppliesVendorroutingrules"]>;
/** Row 28 — a D4 routing rule. Also the shape returned by create/update/retire. */
export type VendorRoutingRuleView = VendorRoutingRulePage["data"][number];

type ParStockPage = Ok<operations["getApiV1SuppliesParstock"]>;
/** Row 32 — one shelf row plus its DERIVED band. Also the shape returned by update/observe. */
export type ParStockView = ParStockPage["data"][number];

/** §8.1 — the whole kit's log, which is the unit an inspector actually asks for. */
export type PerpetualLogView = Ok<operations["getApiV1SuppliesComfortkitdispatchesByDispatchIdPerpetuallog"]>;
export type PerpetualLogLineView = PerpetualLogView["lines"][number];
/** §8.1 — one APPEND-ONLY entry of the DEA 21 CFR §1304 perpetual log. `balanceAfterQuantity` is the
 *  balance AS RECORDED, not one derived at read time: a recomputed balance silently absorbs a missing
 *  entry, which is the exact discrepancy the log exists to expose. */
export type PerpetualLogEntry = PerpetualLogLineView["entries"][number];

// ── request-side shapes (schema-derived) ───────────────────────────────────────────────────────────────

/** D7 / §4.2.1 — the delivery-address snapshot frozen onto the request. */
export type DeliveryAddressInput = ReqBody<operations["postApiV1SuppliesSupplyrequests"]>["deliveryAddress"];

/** One dispatched line on the way IN (§4.2). `lotNumber` / `expirationDate` are optional HERE on purpose:
 *  §3.1.9's CHECK requires them on a controlled line, and the DOMAIN raises the typed refusal
 *  (`M21_LOT_NUMBER_REQUIRED`) rather than the boundary raising a generic 422. */
export type DispatchLineInput = ReqBody<operations["postApiV1SuppliesComfortkitdispatches"]>["contents"][number];

/** One reconciled line on the way IN. `consumedQuantity` is deliberately absent — there is no column to
 *  write it to, and accepting it would let a reconciler believe they had EXPLAINED a shortfall they had
 *  only described (§4.2.2). */
export type ReconcileLineInput =
  ReqBody<operations["postApiV1SuppliesComfortkitreturnsByReturnIdReconcile"]>["perMedicationReconciliation"][number];

/** One template medication on the way IN. */
export type TemplateMedicationInput = ReqBody<operations["postApiV1SuppliesComfortkittemplates"]>["medications"][number];

// ── closed-vocabulary field types (for the shared picklists in supplies-status.ts and the screens) ───────

